import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ToolStore } from '../src/server/store.ts';
import type { Tool } from '../src/shared/types.ts';

export const AVAILABLE_TOOL_ID = 'a';
export const BORROWED_TOOL_ID = 'b';

